package com.ashkan.hotel;

import java.math.BigDecimal;import java.sql.*;import java.util.*;
public final class InventoryRepository extends JdbcDomainRepository {
 public record Product(String id,String sku,String name,String unit,BigDecimal quantity,BigDecimal reorderLevel){public Product{req(id);req(sku);req(name);req(unit);if(quantity==null||quantity.signum()<0||reorderLevel==null||reorderLevel.signum()<0)throw new IllegalArgumentException("Stock values must be non-negative");}}
 private final TtlCache<String,Optional<Product>> cache=new TtlCache<>(CacheSettings.ttlMillis(),CacheSettings.maxEntries()); private final RedisCacheClient redis=new RedisCacheClient(); private String redisKey(String id){return "hotelsphere:inventory:"+id;}
 public InventoryRepository(String u,String n,String p,int z){super(u,n,p,z);}
 public void save(Product x)throws SQLException{withConnection(c->{try(PreparedStatement p=c.prepareStatement("INSERT INTO inventory_products(product_id,sku,name,unit,quantity_on_hand,reorder_level) VALUES(?,?,?,?,?,?) ON CONFLICT(product_id) DO UPDATE SET sku=EXCLUDED.sku,name=EXCLUDED.name,unit=EXCLUDED.unit,reorder_level=EXCLUDED.reorder_level,updated_at=NOW(),deleted_at=NULL")){p.setString(1,x.id());p.setString(2,x.sku());p.setString(3,x.name());p.setString(4,x.unit());p.setBigDecimal(5,x.quantity());p.setBigDecimal(6,x.reorderLevel());p.executeUpdate();}return null;});cache.invalidate(x.id());redis.delete(redisKey(x.id()));}
 public Optional<Product> find(String id)throws SQLException{Optional<Product> cached=cache.get(id);if(cached!=null)return cached;String remote=redis.get(redisKey(id));if(remote!=null){try{String[] a=CacheCodec.unpack(remote,6);Optional<Product> value=Optional.of(new Product(a[0],a[1],a[2],a[3],new BigDecimal(a[4]),new BigDecimal(a[5])));cache.put(id,value);return value;}catch(RuntimeException ignored){redis.delete(redisKey(id));}}Optional<Product> result=withConnection(c->{try(PreparedStatement p=c.prepareStatement("SELECT * FROM inventory_products WHERE product_id=? AND deleted_at IS NULL")){p.setString(1,id);try(ResultSet r=p.executeQuery()){return r.next()?Optional.of(new Product(r.getString("product_id"),r.getString("sku"),r.getString("name"),r.getString("unit"),r.getBigDecimal("quantity_on_hand"),r.getBigDecimal("reorder_level"))):Optional.empty();}}});cache.put(id,result);result.ifPresent(x->redis.set(redisKey(id),CacheCodec.pack(x.id(),x.sku(),x.name(),x.unit(),x.quantity().toPlainString(),x.reorderLevel().toPlainString()),(int)Math.max(1,CacheSettings.ttlMillis()/1000)));return result;}
 public void recordMovement(String productId,String type,BigDecimal delta,String reference)throws SQLException{recordMovementOnce(productId,type,delta,reference,null);}
 public boolean recordMovementOnce(String productId,String type,BigDecimal delta,String reference,String idempotencyKey)throws SQLException{
  if(!Set.of("RECEIPT","ISSUE","ADJUSTMENT","RETURN").contains(type))throw new IllegalArgumentException("Invalid movement type");
  if(delta==null||delta.signum()==0)throw new IllegalArgumentException("Movement quantity cannot be zero");
  if(idempotencyKey!=null&&(idempotencyKey.isBlank()||idempotencyKey.length()>160))throw new IllegalArgumentException("Invalid movement idempotency key");
  boolean applied;
  try(RedisDistributedLock lock=RedisDistributedLock.tryAcquire(redis,"hotelsphere:lock:inventory:"+productId,10000)){
   applied=withConnection(c->{boolean auto=c.getAutoCommit();c.setAutoCommit(false);try{
    if(idempotencyKey!=null){try(PreparedStatement p=c.prepareStatement("INSERT INTO inventory_stock_movements(product_id,movement_type,quantity_delta,reference,idempotency_key) VALUES(?,?,?,?,?) ON CONFLICT(idempotency_key) WHERE idempotency_key IS NOT NULL DO NOTHING")){p.setString(1,productId);p.setString(2,type);p.setBigDecimal(3,delta);p.setString(4,reference);p.setString(5,idempotencyKey);if(p.executeUpdate()==0){ConcurrencyTelemetry.stockDuplicate();c.commit();return false;}}}
    try(PreparedStatement p=c.prepareStatement("UPDATE inventory_products SET quantity_on_hand=quantity_on_hand+?,version=version+1,updated_at=NOW() WHERE product_id=? AND deleted_at IS NULL AND quantity_on_hand+? >= 0")){p.setBigDecimal(1,delta);p.setString(2,productId);p.setBigDecimal(3,delta);if(p.executeUpdate()!=1)throw new SQLException("Product missing or insufficient stock","23514");}
    if(idempotencyKey==null){try(PreparedStatement p=c.prepareStatement("INSERT INTO inventory_stock_movements(product_id,movement_type,quantity_delta,reference) VALUES(?,?,?,?)")){p.setString(1,productId);p.setString(2,type);p.setBigDecimal(3,delta);p.setString(4,reference);p.executeUpdate();}}
    c.commit();return true;
   }catch(SQLException e){c.rollback();throw e;}finally{c.setAutoCommit(auto);}});
  }
  if(applied){cache.invalidate(productId);redis.delete(redisKey(productId));}return applied;
 }

 public List<Product> list(int limit,int offset,String search)throws SQLException{return withConnection(c->{String sql="SELECT * FROM inventory_products WHERE deleted_at IS NULL"+(search==null||search.isBlank()?"":" AND (lower(name) LIKE ? OR lower(sku) LIKE ?)")+" ORDER BY name LIMIT ? OFFSET ?";try(PreparedStatement p=c.prepareStatement(sql)){int i=1;if(search!=null&&!search.isBlank()){String q="%"+search.toLowerCase(Locale.ROOT)+"%";p.setString(i++,q);p.setString(i++,q);}p.setInt(i++,limit);p.setInt(i,offset);try(ResultSet r=p.executeQuery()){List<Product> out=new ArrayList<>();while(r.next())out.add(new Product(r.getString("product_id"),r.getString("sku"),r.getString("name"),r.getString("unit"),r.getBigDecimal("quantity_on_hand"),r.getBigDecimal("reorder_level")));return out;}}});}
 public void softDelete(String id)throws SQLException{withConnection(c->{try(PreparedStatement p=c.prepareStatement("UPDATE inventory_products SET deleted_at=NOW(),updated_at=NOW() WHERE product_id=? AND deleted_at IS NULL")){p.setString(1,id);p.executeUpdate();}return null;});cache.invalidate(id);redis.delete(redisKey(id));}
 private static void req(String s){if(s==null||s.isBlank())throw new IllegalArgumentException("Required inventory field missing");}
}
